import time

def connect_and_send(data):
    try:
        conn = remote('crypto.chal.csaw.io', 4512, timeout=5)
        conn.recvuntil(b'input: ')
        conn.sendline(data)
        response = conn.recvline().strip()
        conn.close()
        return bytes.fromhex(response.decode())
    except Exception as e:
        print(f"Error in connection: {e}")
        return None

def analyze_differences(result1, result2):
    if result1 and result2 and len(result1) == len(result2):
        return bytes(a ^ b for a, b in zip(result1, result2))
    return None

def main():
    # Test patterns
    patterns = [
        (b"AAAAA", "base"),
        (b"BAAAA", "pos0"),
        (b"ABAAA", "pos1"),
        (b"AABAA", "pos2"),
        (b"AAABA", "pos3"),
        (b"AAAAB", "pos4")
    ]

